<?php
/**
 * Proof — a campaign's email (campaigns-lists.md "Decisions taken here" 1, the planning model's): campaign_email_send QUEUES one message per allowed contact (outbound_email, status queued, campaign_id, the
 * template filled for each, the caller the sender), skips and counts the opted-out and the addressless, sends nothing, and is nobody's draft; the worker's `outbox` pass then sends them through email_deliver()
 * — the fake MaluMail receives one message per allowed contact with its own unsubscribe link and Message-ID, the members become `sent`, an opted-out contact got nothing; a 429 or a 502 leaves a row queued to be
 * tried again (five tries), a permanent answer fails it; a contact who opted out since, or a campaign cancelled since, sends nothing; the unsubscribe link marks the member unsubscribed.
 */
require __DIR__ . '/lib.php';
$x = run_tag();
$mb = ensure_mailbox();
$since = last_activity_id();
$mkt = role_actor(31, 'marketing');
pg_run("UPDATE outbound_email SET status = 'failed', error = 'left by an earlier run' WHERE campaign_id IS NOT NULL AND status = 'queued'");     // the pass is global: start from an empty queue
$acc = (int) post_as(26, '/accounts/save.php', ['name' => "Outbox Acct $x"])['json']['record_id'];
$mk = static fn (string $first, string $addr) => contact_with($addr, $first, $acc);
$dom = "out-$x.example.invalid";
$A = $mk('Ann', "ann-$x@$dom");
$B = $mk('Bob', "bob-$x@$dom");
$C = (int) post_as(26, '/contacts/save.php', ['first_name' => 'Cat', 'last_name' => "NoAddr $x", 'account' => $acc])['json']['record_id'];
$D = $mk('Dee', "flaky-$x@$dom");
$E = $mk('Eve', "ratelimited-$x@$dom");
$F = $mk('Fay', "brokenmail-$x@$dom");
$G = $mk('Gus', "suppressed-$x@$dom");
$H = $mk('Hal', "hal-$x@$dom");
$lead = lead_make(26, ['company' => "Outbox lead $x", 'email' => "lead-$x@$dom"]);
post_as(26, '/contacts/opt-out.php', ['contact' => $B, 'channel' => 'email', 'reason' => 'asked']);
$camp = campaign_make(['name' => "Autumn mail $x"]);
post_as(27, '/campaigns/members/add.php', ['campaign' => $camp, 'contacts' => [$A, $B, $C, $D, $E, $F, $G, $H], 'leads' => [$lead]]);
$tpl = (int) post_as(27, '/email/templates/save.php', ['name' => "Camp tpl $x", 'subject' => 'News for {{contact.first_name}}', 'body' => "Hello {{contact.first_name}},\n\nOur autumn news from {{sender.company}}.\n\n{{sender.signature}}", 'is_shared' => 'yes'])['json']['record_id'];
$tplDeal = (int) post_as(27, '/email/templates/save.php', ['name' => "Deal tpl $x", 'subject' => 'About {{deal.title}}', 'body' => 'x', 'is_shared' => 'yes'])['json']['record_id'];
$tplAcc = (int) post_as(27, '/email/templates/save.php', ['name' => "Acct tpl $x", 'subject' => 'For {{account.name}}', 'body' => 'x', 'is_shared' => 'yes'])['json']['record_id'];
$n0 = count(sends());
$queueRows = static fn (): array => q("SELECT o.*, c.first_name FROM outbound_email o JOIN contacts c ON c.id = o.contact_id WHERE o.campaign_id = $camp ORDER BY o.id");
$byContact = static function () use ($queueRows): array { $o = []; foreach ($queueRows() as $r) { $o[(int) $r['contact_id']][] = $r; } return $o; };

echo "1. Who may email a campaign; what is refused before anything is queued\n";
$send = static fn (int $m, array $f) => post_as($m, '/campaigns/email.php', $f + ['campaign' => $camp]);
ok($send(26, ['template' => $tpl, 'confirm' => 'yes'])['code'] === 403, 'a Rep (email.send but not campaigns.manage): 403');
$r = post_role($mkt, '/campaigns/email.php', ['campaign' => $camp, 'template' => $tpl, 'confirm' => 'yes']);
ok($r['code'] === 403, 'Marketing (campaigns.manage but not email.send): 403');
ok($send(29, ['template' => $tpl, 'confirm' => 'yes'])['code'] === 403, 'a Viewer: 403');
$r = $send(27, ['template' => $tpl]);
ok($r['code'] === 422 && field_of($r) === 'confirm', 'no confirm: the field is named');
$r = $send(27, ['confirm' => 'yes']);
ok($r['code'] === 422 && field_of($r) === 'template', 'no template: the field is named');
$r = $send(27, ['template' => $tplDeal, 'confirm' => 'yes']);
ok($r['code'] === 422 && str_contains(message_of($r), '{{deal.title}}'), 'a template that needs a deal is refused, the field named: ' . message_of($r));
$r = $send(27, ['template' => 999999, 'confirm' => 'yes']);
ok($r['code'] === 422 || $r['code'] === 404, 'a template that is not there is refused');
ok($send(27, ['template' => $tpl, 'confirm' => 'yes', 'members' => 'everyone'])['code'] === 422, 'members is planned or all');
ok(post_as(27, '/campaigns/email.php', ['campaign' => 999999, 'template' => $tpl, 'confirm' => 'yes'])['code'] === 404, 'a campaign that is not there: 404');
ok(count($queueRows()) === 0 && count(sends()) === $n0, 'nothing queued and nothing sent by any of those');

echo "2. Queued, not sent\n";
$r = $send(27, ['template' => $tpl, 'confirm' => 'yes']);
$j = $r['json'];
ok($r['code'] === 200 && ($j['queued'] ?? -1) === 6 && ($j['skipped_opted_out'] ?? -1) === 1 && ($j['skipped_no_address'] ?? -1) === 1 && ($j['skipped_leads'] ?? -1) === 1, 'campaign_email_send: 6 queued, 1 opted out and 1 with no address skipped and counted, the lead not emailed — ' . ($j['did'] ?? $r['body']));
$rows = $byContact();
ok(count($queueRows()) === 6 && !isset($rows[$B]) && !isset($rows[$C]), 'six rows; none for Bob (opted out) or Cat (no address)');
$a = $rows[$A][0];
ok($a['status'] === 'queued' && (int) $a['campaign_id'] === $camp && (int) $a['sender_member_id'] === 27 && (int) $a['template_id'] === $tpl && $a['to_address'] === "ann-$x@$dom" && (int) $a['attempts'] === 0, 'the row: queued, the campaign, the sender Marco, the template, her address');
ok($a['subject'] === 'News for Ann' && str_starts_with($a['body_text'], 'Hello Ann,') && !str_contains($a['body_text'], '{{') && $rows[$H][0]['subject'] === 'News for Hal', 'the template is filled for THAT contact: News for Ann, News for Hal');
ok(count(sends()) === $n0, 'the fake MaluMail has received nothing: the request sent nothing');
$log = q("SELECT after::text AS after FROM activity_log WHERE id > :s AND action = 'campaign.email_send'", ['s' => $since]);
$la = json_decode($log[0]['after'] ?? '{}', true);
ok(count($log) === 1 && $la['queued'] === 6 && $la['skipped_opted_out'] === 1 && !str_contains($log[0]['after'], 'Hello') && !str_contains($log[0]['after'], 'autumn'), 'campaign.email_send is logged once with the counts, never a body');
$r2 = $send(27, ['template' => $tpl, 'confirm' => 'yes']);
ok(($r2['json']['queued'] ?? -1) === 0 && ($r2['json']['skipped_already_queued'] ?? 0) === 6 && count($queueRows()) === 6, 'a second click queues nothing: six already waiting');
$ac = $send(27, ['template' => $tplAcc, 'confirm' => 'yes', 'members' => 'all']);
ok(($ac['json']['queued'] ?? -1) === 0, 'members=all with every contact already waiting queues nothing');
$noAcct = (int) post_as(26, '/contacts/save.php', ['first_name' => 'Ned', 'last_name' => "Loner $x", 'email' => "ned-$x@$dom"])['json']['record_id'];
$campX = campaign_make(['name' => "Unfillable $x"]);
post_as(27, '/campaigns/members/add.php', ['campaign' => $campX, 'contacts' => [$noAcct, $A]]);
$r3 = post_as(27, '/campaigns/email.php', ['campaign' => $campX, 'template' => $tplAcc, 'confirm' => 'yes']);
ok(($r3['json']['queued'] ?? -1) === 1 && ($r3['json']['skipped_unfilled'] ?? -1) === 1, 'a contact the template cannot be filled for ({{account.name}}, no account) is skipped and counted');
post_as(27, '/campaigns/save.php', ['campaign' => $campX, 'status' => 'cancelled']);

echo "3. Nobody's draft\n";
$oid = (int) $a['id'];
$un = get_as(27, '/email/unmatched')['json']['data'];
ok($un['drafts'] === [] || !in_array($oid, array_column($un['drafts'], 'draft_id'), true), 'Marco\'s "Your drafts" do not hold a queued campaign message');
$un2 = html_as(27, '/email/unmatched')['body'];
ok(!str_contains($un2, "News for Ann"), 'nor does the page');
$r = post_as(27, '/email/send.php', ['draft' => $oid, 'confirm' => 'yes']);
ok($r['code'] === 404 && count(sends()) === $n0, 'email_send on one is "that draft is not here": the worker alone sends them');
ok(get_as(27, "/email/out/$oid")['code'] === 404, 'the email page is a 404 for it until it is sent');
ok(!str_contains(html_as(27, "/contacts/$A?tab=emails")['body'], 'News for Ann'), 'the contact\'s Emails tab does not list it');
as_member(27);
ok((int) one("SELECT count(*) FROM mcp_emails WHERE campaign_id = $camp") === 0, 'mcp_emails shows none of them (the view hides a queued campaign message)');
$myDraft = (int) post_as(27, '/email/draft.php', ['contact' => $A, 'subject' => "Mine $x", 'body' => 'a draft'])['json']['record_id'];
ok($myDraft > 0 && in_array($myDraft, array_column(get_as(27, '/email/unmatched')['json']['data']['drafts'], 'draft_id'), true), 'a draft of his own is still listed');
$g = get_as(27, "/campaigns/$camp")['json']['data']['email'];
ok($g['queued'] === 6 && $g['sent'] === 0 && $g['failed'] === 0, 'the campaign page counts: 6 waiting, 0 sent, 0 not sent');
$h = html_as(27, "/campaigns/$camp")['body'];
ok(preg_match('/id="campaign-email-queued">6 waiting</', $h) === 1 && str_contains($h, 'id="campaign-email-sent"') && str_contains($h, 'id="campaign-email-failed"'), 'and so does the HTML: #campaign-email-queued · -sent · -failed');

echo "4. The worker sends\n";
$w = worker_at('outbox');
$rep = $w['ran']['outbox'] ?? [];
ok(($w['errors'] ?? []) === [] && $rep['sent'] === 2 && $rep['retried'] === 2 && $rep['failed'] === 1 && $rep['skipped'] === 2 && empty($rep['stub']), 'the pass reports sent 2 (Ann, Hal), retried 2 (502, 429), failed 1 (500), skipped 2 (a suppressed address; Ann\'s message of the campaign cancelled meanwhile): ' . json_encode($rep));
$mine = array_values(array_filter(sends(), static fn ($m) => str_ends_with($m['to'], "@$dom") && !preg_match('/flaky|ratelimited|brokenmail|suppressed/', $m['to'])));
$tos = array_column($mine, 'to');
sort($tos);
ok($tos === ["ann-$x@$dom", "hal-$x@$dom"], 'the fake MaluMail received exactly one message each for Ann and Hal — none for Bob (opted out) or Cat (no address)');
$ma = array_values(array_filter($mine, static fn ($m) => $m['to'] === "ann-$x@$dom"))[0];
preg_match('#/u/([a-f0-9]{48})#', $ma['text'], $tk);
ok(strlen($tk[1] ?? '') === 48 && str_contains($ma['html'], '/u/' . $tk[1]) && $ma['subject'] === 'News for Ann' && str_starts_with($ma['text'], 'Hello Ann,') && $ma['from'] === 'crm@example.invalid' && $ma['from_name'] === 'SMOKE Marco', 'Ann\'s message: filled, From the business under Marco\'s name, with an unsubscribe link in both parts');
ok(preg_match('/^<([a-f0-9]{64})@example\.invalid>$/', (string) $ma['message_id'], $mm) === 1 && $mm[1] === hash('sha256', $tk[1]), 'its Message-ID is ours: the SHA-256 of that token');
$mh = array_values(array_filter($mine, static fn ($m) => $m['to'] === "hal-$x@$dom"))[0];
preg_match('#/u/([a-f0-9]{48})#', $mh['text'], $tkh);
ok(($tkh[1] ?? '') !== ($tk[1] ?? '') && ($ma['reply_to'] ?? null) === MAILBOX, 'Hal\'s link is not Ann\'s; Reply-To is the logging mailbox');
$rows = $byContact();
ok($rows[$A][0]['status'] === 'sent' && $rows[$A][0]['sent_at'] !== null && $rows[$A][0]['message_id'] === $ma['message_id'] && $rows[$H][0]['status'] === 'sent', 'Ann\'s and Hal\'s rows are sent, with our Message-ID');
ok(member_status($camp, $A) === 'sent' && member_status($camp, $H) === 'sent' && member_status($camp, $B) === 'planned' && member_status($camp, $C) === 'planned' && member_status($camp, $F) === 'planned', 'their members moved from planned to sent; Bob (nothing went), Cat and Fay are still planned');
$act = email_acts('outbound_email_id', (int) $rows[$A][0]['id']);
ok(count($act) === 1 && $act[0]['kind'] === 'email' && $act[0]['email_direction'] === 'out' && $act[0]['done_at'] !== null && (int) $act[0]['contact_id'] === $A && (int) $act[0]['owner_member_id'] === 27 && $act[0]['source'] === 'cron', 'one done outgoing email activity on Ann, Marco\'s, made by the worker');
ok((int) one('SELECT usage_count FROM email_templates WHERE id = :t', ['t' => $tpl]) === 2, 'the template\'s use is counted: 2');
$f = $rows[$F][0];
ok($f['status'] === 'failed' && str_contains((string) $f['error'], '500'), 'a permanent answer (500) fails the row, with the sentence: ' . $f['error']);
$g = $rows[$G][0];
ok($g['status'] === 'suppressed' && str_contains((string) $g['error'], 'suppressed'), 'a suppressed address is suppressed, not retried');
$d = $rows[$D][0];
$e = $rows[$E][0];
ok($d['status'] === 'queued' && (int) $d['attempts'] === 1 && $d['retry_at'] !== null && $e['status'] === 'queued' && (int) $e['attempts'] === 1 && str_contains((string) $e['error'], '429'), 'a 502 and a 429 leave the row queued, one attempt counted, retry_at set: ' . $e['error']);
$h = html_as(27, "/campaigns/$camp")['body'];
ok(preg_match('/id="campaign-email-queued">2 waiting</', $h) === 1 && preg_match('/id="campaign-email-sent">2 sent</', $h) === 1 && preg_match('/id="campaign-email-failed">2 not sent</', $h) === 1 && str_contains($h, 'id="campaign-email-failures"'), 'the page now: 2 waiting, 2 sent, 2 not sent, the latest failures named');
$ev = q("SELECT * FROM activity_log WHERE id > :s AND action = 'email.send' AND (after->>'campaign_id')::bigint = :c", ['s' => $since, 'c' => $camp]);
ok(count($ev) === 4 && (int) $ev[0]['actor_member_id'] === 27 && $ev[0]['source'] === 'cron' && !str_contains(json_encode($ev), 'Hello'), 'email.send is logged for each that ended (sent, failed, suppressed), by Marco, source cron, no body');
$w2 = worker_at('outbox')['ran']['outbox'];
ok($w2['sent'] === 0 && $w2['retried'] === 0 && $w2['failed'] === 0, 'run again at once: nothing is due (the retries wait; the sent are not sent twice)');
ok(count(array_filter(sends(), static fn ($m) => $m['to'] === "ann-$x@$dom")) === 1, 'Ann has still received exactly one message');
ok(in_array($myDraft, array_column(get_as(27, '/email/unmatched')['json']['data']['drafts'], 'draft_id'), true) && one('SELECT status FROM outbound_email WHERE id = :i', ['i' => $myDraft]) === 'queued', 'a person\'s own draft is never touched by the pass');

echo "5. Tried again, and given up on\n";
$t1 = date(DATE_ATOM, time() + 120);
$w3 = worker_at('outbox', $t1)['ran']['outbox'];
ok($w3['retried'] === 2 && $w3['sent'] === 0, 'two minutes on, both are tried again (a retry after one minute)');
$dd = q('SELECT * FROM outbound_email WHERE id = :i', ['i' => $d['id']])[0];
ok((int) $dd['attempts'] === 2 && $dd['status'] === 'queued', 'attempts counted: 2');
pg_run("UPDATE outbound_email SET to_address = 'dee-$x@$dom' WHERE id = " . (int) $d['id']);        // the relay is back for Dee: her address is plain now
$w4 = worker_at('outbox', date(DATE_ATOM, time() + 600))['ran']['outbox'];
ok($w4['sent'] === 1 && member_status($camp, $D) === 'sent' && one('SELECT status FROM outbound_email WHERE id = :i', ['i' => $d['id']]) === 'sent', 'Dee\'s row goes at the next try and her member becomes sent');
$clock = time() + 600;
foreach ([2, 3, 4] as $i) { $clock += 3600; worker_at('outbox', date(DATE_ATOM, $clock)); }
$ee = q('SELECT * FROM outbound_email WHERE id = :i', ['i' => $e['id']])[0];
ok($ee['status'] === 'failed' && str_contains((string) $ee['error'], '429') && (int) $ee['attempts'] === 4, 'Eve\'s 429 is tried five times in all, then it is failed with the sentence: attempts ' . $ee['attempts'] . ' — ' . $ee['error']);
ok(member_status($camp, $E) === 'planned', 'and her member is still planned');

echo "6. A contact who opts out after it was queued; a campaign cancelled after\n";
$I = $mk('Ida', "ida-$x@$dom");
$J = $mk('Jay', "jay-$x@$dom");
$campY = campaign_make(['name' => "Changed minds $x"]);
post_as(27, '/campaigns/members/add.php', ['campaign' => $campY, 'contacts' => [$I, $J]]);
$qq = post_as(27, '/campaigns/email.php', ['campaign' => $campY, 'template' => $tpl, 'confirm' => 'yes']);
ok(($qq['json']['queued'] ?? 0) === 2, 'two queued for the next campaign');
post_as(26, '/contacts/opt-out.php', ['contact' => $I, 'channel' => 'email', 'reason' => 'asked']);
$nb = count(sends());
$w5 = worker_at('outbox')['ran']['outbox'];
ok($w5['sent'] === 1 && $w5['skipped'] === 1 && count(sends()) === $nb + 1, 'Ida opted out in between: skipped, nothing goes to her; Jay\'s goes');
$ri = q('SELECT status, error FROM outbound_email WHERE campaign_id = :c AND contact_id = :k', ['c' => $campY, 'k' => $I])[0];
ok($ri['status'] === 'suppressed' && str_contains($ri['error'], 'Ida') && str_contains($ri['error'], 'opted out'), 'her row is suppressed and says why: ' . $ri['error']);
$campZ = campaign_make(['name' => "Stopped $x"]);
$K = $mk('Kit', "kit-$x@$dom");
post_as(27, '/campaigns/members/add.php', ['campaign' => $campZ, 'contacts' => [$K]]);
post_as(27, '/campaigns/email.php', ['campaign' => $campZ, 'template' => $tpl, 'confirm' => 'yes']);
post_as(27, '/campaigns/save.php', ['campaign' => $campZ, 'status' => 'cancelled']);
$nb = count(sends());
$w6 = worker_at('outbox')['ran']['outbox'];
$rk = q('SELECT status, error FROM outbound_email WHERE campaign_id = :c', ['c' => $campZ])[0];
ok($w6['skipped'] === 1 && count(sends()) === $nb && $rk['status'] === 'failed' && str_contains($rk['error'], 'cancelled'), 'a campaign cancelled in between sends nothing: skipped, marked with the reason');
ok(post_as(27, '/campaigns/email.php', ['campaign' => $campZ, 'template' => $tpl, 'confirm' => 'yes'])['code'] === 422, 'and a cancelled campaign is not emailed');

echo "7. The unsubscribe link; planned and all\n";
$jar = jar();
$gt = req('GET', "/u/{$tk[1]}", ['jar' => $jar]);
preg_match('/name="csrf_token" value="([a-f0-9]+)"/', $gt['body'], $cs);
$pp = req('POST', "/u/{$tk[1]}", ['jar' => $jar, 'form' => ['csrf_token' => $cs[1] ?? '']]);
ok($pp['code'] === 200 && (bool) one('SELECT email_opt_out FROM contacts WHERE id = :c', ['c' => $A]) && member_status($camp, $A) === 'unsubscribed', 'Ann unsubscribes through her link: opted out, and her member is `unsubscribed` in that campaign');
ok(preg_match('/bg-soft-dark text-dark" id="campaign-member-\d+-status">Unsubscribed</', html_as(27, "/campaigns/$camp")['body']) === 1, 'shown dark, as the vocabulary says');
$again = post_as(27, '/campaigns/email.php', ['campaign' => $camp, 'template' => $tpl, 'confirm' => 'yes']);
$tq = array_map('intval', array_column(q("SELECT contact_id FROM outbound_email WHERE campaign_id = :c AND status = 'queued'", ['c' => $camp]), 'contact_id'));
sort($tq);
$want = [$E, $F, $G];
sort($want);
ok(($again['json']['queued'] ?? -1) === 3 && $tq === $want, 'members=planned (the default): the sent and the unsubscribed are not emailed again; Eve, Fay and Gus — still planned, their last try failed — are queued afresh');
pg_run("UPDATE outbound_email SET status = 'failed' WHERE campaign_id = $camp AND status = 'queued'");
$all = post_as(27, '/campaigns/email.php', ['campaign' => $camp, 'template' => $tpl, 'confirm' => 'yes', 'members' => 'all']);
$rowsAll = q("SELECT contact_id FROM outbound_email WHERE campaign_id = :c AND status = 'queued'", ['c' => $camp]);
$to = array_map('intval', array_column($rowsAll, 'contact_id'));
ok(in_array($H, $to, true) && !in_array($A, $to, true) && !in_array($B, $to, true), 'members=all: Hal (sent) is emailed again, Ann (unsubscribed) and Bob (opted out) are not');

echo "8. The pass and the registry\n";
$rep = worker_at('outbox')['ran']['outbox'] ?? [];
ok(isset($rep['sent'], $rep['skipped'], $rep['retried'], $rep['failed']) && !isset($rep['stub']), 'the outbox pass answers sent · skipped · retried · failed (slice 8 adds its half to the same four)');
exec('php ' . escapeshellarg(dirname(__DIR__, 3) . '/bin/build_action_registry.php') . ' --check 2>&1', $o, $rc);
ok($rc === 0, 'the registry and the approvals match the manifest');
$reg = json_decode((string) file_get_contents(dirname(__DIR__, 3) . '/mcp/action_registry.json'), true);
ok(($reg['actions']['campaign_email_send']['approval'] ?? '') === 'external_send' && ($reg['actions']['campaign_email_send']['confirm'] ?? false) === true, 'campaign_email_send pauses an agent: external_send, with confirm');
finish();
